#include "black_internal.h"

typedef struct Sym { char *name; BlackType *type; int is_function; struct Sym *next; } Sym;
typedef struct Scope { Sym *syms; struct Scope *parent; } Scope;
static Sym *lookup(Scope*s,const char*n){for(;s;s=s->parent)for(Sym*x=s->syms;x;x=x->next)if(!strcmp(x->name,n))return x;return NULL;}
static int add(Scope*s,const char*n,BlackType*t,int fn){if(lookup(s,n)&&lookup(s,n)->type)return -1;Sym*x=calloc(1,sizeof(*x));x->name=black_xstrndup(n,strlen(n));x->type=black_type_clone(t);x->is_function=fn;x->next=s->syms;s->syms=x;return 0;}
static void scope_free(Scope*s){Sym*x=s->syms;while(x){Sym*n=x->next;free(x->name);free(x);x=n;}free(s);}
static BlackType *builtin(BlackTypeKind k){return black_type_new(k);}
static void resolve_type(BlackProgram*p,BlackType*t){
    if(!t)return;
    if(t->kind==BLACK_TYPE_STRUCT){
        for(size_t i=0;i<p->count;i++) if(p->decls[i]->kind==BLACK_DECL_STRUCT && p->decls[i]->name && t->as.record.name && !strcmp(p->decls[i]->name,t->as.record.name)){
            t->as.record.fields=p->decls[i]->as.structure.fields; t->as.record.field_count=p->decls[i]->as.structure.field_count; break;
        }
        for(size_t i=0;i<t->as.record.field_count;i++) resolve_type(p,t->as.record.fields[i].type);
    } else if(t->kind==BLACK_TYPE_POINTER) resolve_type(p,t->as.pointer.base);
    else if(t->kind==BLACK_TYPE_ARRAY) resolve_type(p,t->as.array.element);
    else if(t->kind==BLACK_TYPE_FUNCTION){resolve_type(p,t->as.function.return_type);for(size_t i=0;i<t->as.function.param_count;i++)resolve_type(p,t->as.function.params[i]);}
}
static int check_expr(BlackProgram*p,Scope*s,BlackExpr*e,BlackType**out,BlackError*er){if(!e)return -1;BlackType*t=NULL;switch(e->kind){case BLACK_EXPR_INT:t=builtin(BLACK_TYPE_U64);break;case BLACK_EXPR_BOOL:t=builtin(BLACK_TYPE_BOOL);break;case BLACK_EXPR_CHAR:t=builtin(BLACK_TYPE_U8);break;case BLACK_EXPR_STRING:{t=black_type_new(BLACK_TYPE_POINTER);t->as.pointer.base=builtin(BLACK_TYPE_U8);break;}case BLACK_EXPR_NAME:{Sym*x=lookup(s,e->as.name);if(!x){black_set_error(er,e->location,"undefined name '%s'",e->as.name);return -1;}resolve_type(p,x->type);t=x->type;break;}case BLACK_EXPR_UNARY:{BlackType*x=NULL;if(check_expr(p,s,e->as.unary.value,&x,er)<0)return -1;if(e->as.unary.op==BLACK_UN_DEREF){if(!x||x->kind!=BLACK_TYPE_POINTER){black_set_error(er,e->location,"cannot dereference a non-pointer");return -1;}t=x->as.pointer.base;}else if(e->as.unary.op==BLACK_UN_ADDR){t=black_type_new(BLACK_TYPE_POINTER);t->as.pointer.base=black_type_clone(x);}else t=x;break;}case BLACK_EXPR_ASSIGN:{BlackType*l=NULL,*r=NULL;if(check_expr(p,s,e->as.assign.left,&l,er)<0||check_expr(p,s,e->as.assign.right,&r,er)<0)return -1;if(e->as.assign.left->kind!=BLACK_EXPR_NAME&&e->as.assign.left->kind!=BLACK_EXPR_UNARY&&e->as.assign.left->kind!=BLACK_EXPR_INDEX&&e->as.assign.left->kind!=BLACK_EXPR_MEMBER){black_set_error(er,e->location,"left side of assignment is not writable");return -1;}if(!black_type_equal(l,r)&&!(black_type_is_integer(l)&&black_type_is_integer(r))&&!(l->kind==BLACK_TYPE_POINTER&&r->kind==BLACK_TYPE_POINTER)){black_set_error(er,e->location,"assignment type mismatch: %s <- %s",black_type_name(l),black_type_name(r));return -1;}t=l;break;}case BLACK_EXPR_BINARY:{BlackType*a=NULL,*b=NULL;if(check_expr(p,s,e->as.binary.left,&a,er)<0||check_expr(p,s,e->as.binary.right,&b,er)<0)return -1;if((black_type_is_integer(a)&&black_type_is_integer(b))||(a->kind==BLACK_TYPE_POINTER&&black_type_is_integer(b))){t=a;}else if(e->as.binary.op>=BLACK_BIN_EQ&&e->as.binary.op<=BLACK_BIN_LOGICAL_OR)t=builtin(BLACK_TYPE_BOOL);else{black_set_error(er,e->location,"invalid operands for binary operator");return -1;}break;}case BLACK_EXPR_CALL:{BlackType*f=NULL;if(check_expr(p,s,e->as.call.callee,&f,er)<0)return -1;if(f->kind==BLACK_TYPE_POINTER)f=f->as.pointer.base;if(f->kind!=BLACK_TYPE_FUNCTION){black_set_error(er,e->location,"called object is not a function");return -1;}if(f->as.function.param_count!=e->as.call.arg_count){black_set_error(er,e->location,"wrong argument count: expected %zu, got %zu",f->as.function.param_count,e->as.call.arg_count);return -1;}for(size_t i=0;i<e->as.call.arg_count;i++){BlackType*a=NULL;if(check_expr(p,s,e->as.call.args[i],&a,er)<0)return -1;if(!black_type_equal(a,f->as.function.params[i])&&!(black_type_is_integer(a)&&black_type_is_integer(f->as.function.params[i]))){black_set_error(er,e->as.call.args[i]->location,"argument %zu has wrong type",i+1);return -1;}}t=f->as.function.return_type;break;}case BLACK_EXPR_INDEX:{BlackType*b=NULL,*i=NULL;if(check_expr(p,s,e->as.index.base,&b,er)<0||check_expr(p,s,e->as.index.index,&i,er)<0)return -1;if(!black_type_is_integer(i)||!(b->kind==BLACK_TYPE_POINTER||b->kind==BLACK_TYPE_ARRAY)){black_set_error(er,e->location,"invalid array/pointer indexing");return -1;}t=b->kind==BLACK_TYPE_POINTER?b->as.pointer.base:b->as.array.element;break;}case BLACK_EXPR_MEMBER:{BlackType*b=NULL;if(check_expr(p,s,e->as.member.base,&b,er)<0)return -1;if(b->kind!=BLACK_TYPE_STRUCT){black_set_error(er,e->location,"member access requires struct");return -1;}int found=0;for(size_t i=0;i<b->as.record.field_count;i++)if(!strcmp(b->as.record.fields[i].name,e->as.member.member)){t=b->as.record.fields[i].type;found=1;break;}if(!found){black_set_error(er,e->location,"unknown struct member '%s'",e->as.member.member);return -1;}break;}default:break;}e->resolved_type=t;*out=t;return 0;}
static int check_stmt(BlackProgram*p,Scope*s,BlackStmt*st,BlackType*ret,BlackError*er){switch(st->kind){case BLACK_ST_BLOCK:{Scope*n=calloc(1,sizeof(*n));n->parent=s;for(size_t i=0;i<st->as.block.count;i++)if(check_stmt(p,n,st->as.block.items[i],ret,er)<0){scope_free(n);return -1;}scope_free(n);return 0;}case BLACK_ST_LET:{resolve_type(p,st->as.let.type);if(add(s,st->as.let.name,st->as.let.type,0)<0){black_set_error(er,st->location,"duplicate variable '%s'",st->as.let.name);return -1;}if(st->as.let.initializer){BlackType*x=NULL;if(check_expr(p,s,st->as.let.initializer,&x,er)<0)return -1;if(!black_type_equal(x,st->as.let.type)&&!(black_type_is_integer(x)&&black_type_is_integer(st->as.let.type))&&!(st->as.let.type->kind==BLACK_TYPE_POINTER&&st->as.let.initializer->kind==BLACK_EXPR_INT)){black_set_error(er,st->location,"initializer type mismatch");return -1;}}return 0;}case BLACK_ST_EXPR:{BlackType*x;return check_expr(p,s,st->as.expr.expr,&x,er);}case BLACK_ST_RETURN:{if(!st->as.ret.expr){if(ret->kind!=BLACK_TYPE_VOID){black_set_error(er,st->location,"missing return value");return -1;}return 0;}BlackType*x;if(check_expr(p,s,st->as.ret.expr,&x,er)<0)return -1;if(ret->kind==BLACK_TYPE_VOID||(!black_type_equal(x,ret)&&!(black_type_is_integer(x)&&black_type_is_integer(ret)))){black_set_error(er,st->location,"return type mismatch: expected %s, got %s",black_type_name(ret),black_type_name(x));return -1;}return 0;}case BLACK_ST_IF:{BlackType*x;if(check_expr(p,s,st->as.if_stmt.condition,&x,er)<0)return -1;if(check_stmt(p,s,st->as.if_stmt.then_branch,ret,er)<0)return -1;if(st->as.if_stmt.else_branch&&check_stmt(p,s,st->as.if_stmt.else_branch,ret,er)<0)return -1;return 0;}default:return 0;}}
int black_semantic_check(BlackProgram*p,BlackError*er){Scope global={0};for(size_t i=0;i<p->count;i++){BlackDecl*d=p->decls[i];if(d->kind==BLACK_DECL_FUNCTION){for(size_t z=0;z<d->as.function.param_count;z++)resolve_type(p,d->as.function.params[z].type);resolve_type(p,d->as.function.return_type);BlackType*f=black_type_new(BLACK_TYPE_FUNCTION);f->as.function.param_count=d->as.function.param_count;f->as.function.params=calloc(f->as.function.param_count,sizeof(BlackType*));for(size_t j=0;j<f->as.function.param_count;j++)f->as.function.params[j]=d->as.function.params[j].type;f->as.function.return_type=d->as.function.return_type;if(add(&global,d->name,f,1)<0){black_set_error(er,d->location,"duplicate declaration '%s'",d->name);return -1;}}else if(d->kind==BLACK_DECL_STRUCT){for(size_t z=0;z<d->as.structure.field_count;z++)resolve_type(p,d->as.structure.fields[z].type);BlackType*t=black_type_new(BLACK_TYPE_STRUCT);t->as.record.name=d->name;if(add(&global,d->name,t,0)<0){black_set_error(er,d->location,"duplicate declaration '%s'",d->name);return -1;}}else if(d->kind==BLACK_DECL_EXTERN_VAR){resolve_type(p,d->as.extern_var.type);if(add(&global,d->name,d->as.extern_var.type,0)<0){black_set_error(er,d->location,"duplicate declaration '%s'",d->name);return -1;}}}
for(size_t i=0;i<p->count;i++){BlackDecl*d=p->decls[i];if(d->kind!=BLACK_DECL_FUNCTION||!d->as.function.body)continue;Scope fn={0};fn.parent=&global;for(size_t j=0;j<d->as.function.param_count;j++)if(add(&fn,d->as.function.params[j].name,d->as.function.params[j].type,0)<0){black_set_error(er,d->location,"duplicate parameter '%s'",d->as.function.params[j].name);/* local scope cleanup */ { Sym *q=fn.syms; while(q){Sym*n=q->next;free(q->name);free(q);q=n;} } return -1;}if(check_stmt(p,&fn,d->as.function.body,d->as.function.return_type,er)<0){/* fn stack owns no heap sym after manual cleanup */Sym*x=fn.syms;while(x){Sym*n=x->next;free(x->name);free(x);x=n;}return -1;}Sym*x=fn.syms;while(x){Sym*n=x->next;free(x->name);free(x);x=n;}}
/* Function types in the global table borrow AST types, so only free symbol nodes. */Sym*x=global.syms;while(x){Sym*n=x->next;free(x->name);if(x->is_function)black_type_free(x->type);else black_type_free(x->type);free(x);x=n;}return 0;}
